const o = phi.observe();
const btn = o.nodes.find(n => (n.name||'').includes('Find baggage allowance'));
const r = phi.click(btn.ref);
phi.sleep(2500);
const o2 = phi.observe();
return { clicked: btn.ref, r, url: o2.url, text: o2.text.slice(0, 3000), nodes: o2.nodes.slice(0, 50).map(n => n.ref + '. ' + n.role + ' ' + (n.name||'') + ' ' + (n.owner||'')) };

const t = phi.text();
const heads = phi.query("h1,h2,h3,h4", { limit: 60 });
const tables = phi.query("table", { limit: 10 });
return { len: t.length, tail: t.slice(0, 200), heads: heads.items.map(h => h.text), tableCount: tables.total, tables: tables.items.map(x => (x.text||'').slice(0,600)) };

const links = phi.query("main a, a", { fields: ["href"], limit: 200 });
const rel = links.items.filter(l => /baggage|allowance/i.test(l.href||'') || /baggage|allowance/i.test(l.text||''));
const t = phi.text();
const idx = t.indexOf('baggage allowance');
phi.look();
return { relCount: rel.length, rel: rel, snippet: t.slice(Math.max(0,idx-200), idx+2200) };

const r = phi.goto("https://www.qatarairways.com/en/baggage/allowance.html");
phi.sleep(2000);
const t = phi.text();
return { r, url: phi.observe().url, len: t.length, text: t.slice(0, 4000) };

const cells = phi.query("table tr", { limit: 30 });
const obs = phi.observe({ within: "table" });
const t = phi.text();
const i = t.indexOf("Baggage allowance per fare type");
phi.keep("qatar_econ", { snippet: t.slice(i, i + 900), rows: cells.items.map(x => x.text) });
return { tableCount: cells.total, rows: cells.items.map(x => x.text).slice(0, 20).map(s => s.replace(/\s+/g, " ").slice(0, 300)), obsNodes: obs.nodes.map(n => `${n.ref}. ${n.role} "${n.name||n.text}"`).slice(0,40) };

// Read the allowance table structure precisely (row/column spans) for the Economy section
const grid = phi.js(() => {
  const tables = [...document.querySelectorAll("table")];
  const out = [];
  for (const t of tables) {
    const txt = t.innerText || "";
    if (!/Baggage allowance per fare type|Economy Class/i.test(txt)) continue;
    const rows = [];
    for (const tr of t.querySelectorAll("tr")) {
      const cells = [...tr.querySelectorAll("th,td")].map(c => ({
        t: (c.innerText || "").replace(/\s+/g, " ").trim().slice(0, 160),
        cs: c.colSpan || 1,
        rs: c.rowSpan || 1,
        tag: c.tagName.toLowerCase()
      }));
      rows.push(cells);
    }
    out.push({ rect: t.getBoundingClientRect().toJSON(), rows });
  }
  return out;
});
return { tables: grid.length, data: grid.map(g => g.rows) };

const t = phi.text();
const i = t.indexOf("Baggage allowance per fare type");
const block = t.slice(i, i + 700).replace(/\s+/g, " ");
const carryOn = (t.match(/Carry-on baggage 1 piece up to [0-9]+kg \([0-9]+lb\)\^?/) || [])[0];
const checkedAfrica = (t.match(/1 piece up to 23kg \(50lb\)/) || [])[0];
const checkedOther = (t.match(/20kg \(44lb\) 25kg \(55lb\) 30kg \(66lb\) 35kg \(77lb\)/) || [])[0];
phi.keep("qatar_econ", { block, carryOn, checkedAfrica, checkedOther, url: location.href });
return { block, carryOn, checkedAfrica, checkedOther };

// Bring the fare-type matrix on screen and read it there
const res = phi.js(() => {
  const els = [...document.querySelectorAll("h1,h2,h3,h4,p,span,div,table")];
  const hit = els.find(e => /Baggage allowance per fare type/i.test(e.innerText || "") && (e.innerText || "").length < 3000);
  if (hit) hit.scrollIntoView({ block: "center" });
  return { scrolled: !!hit, tag: hit ? hit.tagName : null };
});
phi.waitForNetworkIdle({ timeoutMs: 3000 });
const t = phi.text();
const i = t.indexOf("Economy Lite");
const block = t.slice(Math.max(0, i - 200), i + 900).replace(/\s+/g, " ");
phi.keep("qatar_econ_clean", {
  url: "https://www.qatarairways.com/en/baggage/allowance.html",
  carryOn: "1 piece up to 7kg (15lb) - applies to all Economy fare types",
  checked_Africa_Americas: "Economy Lite: 1 piece up to 23kg (50lb); Economy Classic/Convenience/Comfort: 2 pieces up to 23kg (50lb) each",
  checked_other: "Economy Lite 20kg (44lb); Classic 25kg (55lb); Convenience 30kg (66lb); Comfort 35kg (77lb)",
  block
});
return { res, block };

const a = phi.recall("qatar_econ");
const b = phi.recall("qatar_econ_clean");
return { a, b: { ...b, block: b.block.slice(0, 400) } };

