  checked_all_other_destinations: "Lite 20 kg (44 lb); Classic 25 kg (55 lb); Convenience 30 kg (66 lb); Comfort 35 kg (77 lb)"
});
const v = phi.text();
return { hasTable: /Baggage allowance per fare type/.test(v), has7kg: /1 piece up to 7kg \(15lb\)/.test(v), has20kg: /20kg \(44lb\)/.test(v), has35kg: /35kg \(77lb\)/.test(v) };
